func loadOrders(id string) ([]Order, error) {
    user, err := loadUser(id)          // value + error, no box
    if err != nil {
        return nil, fmt.Errorf("load user %s: %w", id, err)
    }
    orders, err := fetchOrders(user)   // runs only on success
    if err != nil {
        return nil, err
    }
    return orders, nil
}
